package ru.meguboom.mobile;
import org.junit.Test;import org.json.*;import static org.junit.Assert.*;
public class ProgressRecordsTest {
 static final String A="11111111-1111-4111-8111-111111111111",B="22222222-2222-4222-8222-222222222222";
 JSONObject record(long pos,long time,String device,boolean done)throws Exception{return new JSONObject().put("positionMs",pos).put("durationMs",100000).put("updatedAt",time).put("deviceId",device).put("completed",done);}
 @Test public void newerRewindAndUnmarkReplaceOlderCompletion()throws Exception {JSONObject target=new JSONObject().put("file_1",record(99000,50,A,true));ProgressRecords.merge(target,new JSONObject().put("file_1",record(1000,51,B,false)));assertEquals(1000,target.getJSONObject("file_1").getLong("positionMs"));assertFalse(target.getJSONObject("file_1").getBoolean("completed"));}
 @Test public void tieBreakIsDeviceIdAndOlderIsIgnored()throws Exception {JSONObject t=new JSONObject().put("id",record(2,5,B,false));ProgressRecords.merge(t,new JSONObject().put("id",record(99,5,A,true)));assertEquals(2,t.getJSONObject("id").getInt("positionMs"));}
 @Test public void rejectsMalformedAndOversizeDocuments()throws Exception {JSONObject d=new JSONObject().put("version",1).put("deviceId",A).put("entries",new JSONObject().put("id",record(-1,4,A,false)));assertThrows(Exception.class,()->ProgressRecords.parse(d.toString()));d.getJSONObject("entries").getJSONObject("id").put("positionMs",0).put("completed","false");assertThrows(Exception.class,()->ProgressRecords.parse(d.toString()));assertThrows(Exception.class,()->ProgressRecords.parse(" ".repeat(2097153)));}
 @Test public void aliasesUseOriginalFileIdNeverTitle()throws Exception {assertEquals("abc_123",ProgressRecords.fileId(new JSONObject().put("id","download-drive-abc_123").put("downloadOf","drive-abc_123").put("title","same")));assertEquals("",ProgressRecords.fileId(new JSONObject().put("id","local-title").put("title","same")));}
 @Test public void sharedDesktopFixtureRoundTripsMilliseconds()throws Exception {java.nio.file.Path p=java.nio.file.Paths.get("../../scripts/fixtures/progress-v1.json");if(!java.nio.file.Files.exists(p))p=java.nio.file.Paths.get("../scripts/fixtures/progress-v1.json");JSONObject entries=ProgressRecords.parse(new String(java.nio.file.Files.readAllBytes(p),java.nio.charset.StandardCharsets.UTF_8));assertEquals(123456,entries.getJSONObject("book-A").getLong("positionMs"));assertTrue(entries.getJSONObject("book-B").getBoolean("completed"));assertEquals(2,ProgressRecords.parse(ProgressRecords.document(A,entries).toString()).length());}
 @Test public void rejectsFractionalUnsafeNumbersAndPrototypeIds()throws Exception {for(String value:new String[]{"1.5","9007199254740992","-1","\"100\""}){String json="{\"version\":1,\"deviceId\":\""+A+"\",\"entries\":{\"id\":{\"positionMs\":"+value+",\"durationMs\":100,\"updatedAt\":1,\"deviceId\":\""+A+"\",\"completed\":false}}}";assertThrows(Exception.class,()->ProgressRecords.parse(json));}assertFalse(ProgressRecords.validId("__proto__"));assertFalse(ProgressRecords.uuid("AAAAAAAA-1111-4111-8111-111111111111"));}
}
